#!/usr/bin/env python3
"""Classic 128x32 DMD frames of every display effect, generated by the ROM's own code (Unicorn), no PinMAME.

For each effect the ROM routine runs with the ROM's drawing code; every `dmd_show_pages` (0x27830) / flip (0x27a70) gives one frame
(page 0 = foreground, page 1 = background, mixed by the display rule, deff_frames.mix). The frame time is the OS tick of the flip
(16.000 ms per tick: IO ISR 0x12070 every 250 us, 0x40 interrupts per tick).

Output (rom_data/dmd_code/): deff_NNN/frames/NNN.png (128x32, 16 grey levels x 17), deff_NNN/timing.json, index.csv.
The recipes (arguments, RAM state, random draws) are in RECIPES: an effect not listed runs with its arguments 0 and the factory game
state of deff_state.game(). `reference_capture.gif` (PinMAME) is read only to CONTROL the result (columns of the match in index.csv).
Usage: TRON_ROM=trn_174h.bin gen_code_dmd.py [OUT_DIR] [effect ...]
"""
import csv, glob, json, os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from multiprocessing import Pool
import deff_frames as F
import deff_state as S

TICK_MS = 16.0
ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..")
MEDIA = os.path.join(ROOT, "mpf_package", "media", "dmd")
# effect -> dict(args, ram, rng): the neutral state the effect needs (read from the effect's code, docs/dmd_from_code.md)
RECIPES = {
    9: dict(ram=lambda: {**S.game(), **S.error_log(10)}),                 # error summary counts ten type-2 records
    14: dict(args=[0], ram=S.game),
    111: dict(args=[6], rng=7),                                              # clip variant 7, "6 more to start"
}
MAX_INSNS = 6000000


def recipe(e):
    r = dict(RECIPES.get(e, {}))
    ram = r.get("ram", S.game)
    return dict(args=r.get("args", [0, 0, 0, 0]), ram=ram() if callable(ram) else ram, rng=r.get("rng"))


def frames_of(e):
    r = recipe(e)
    try:
        snaps, ticks = F.frames(e, args=r["args"], ram=r["ram"], rng=r["rng"], init=S.INIT, max_insns=MAX_INSNS)
    except Exception as x:                                                    # recorded, not hidden
        return e, None, "ERROR %s" % x
    return e, ([(bytes(F.mix(a, b)), t) for (_, _, a, b), t in zip(snaps, ticks)] if snaps else []), ""


def attract_pages():
    """Effect 1 (deff_001_attract_pages 0x01034364) spawns one child task per page of attr_page_table (RAM 0x36e10, initialised from the ROM
    image at file 0x36e10: pairs of (shown-predicate, page routine), 8 bytes each, ends with a null routine). Each page routine is run
    alone (the parent only waits for it): returns [(index, routine address)]."""
    import struct
    import deff_unicorn as D
    out, i = [], 0
    while True:
        pred, page = struct.unpack_from("<II", D.ROM, 0x36e10 + 8 * i)
        if page == 0:
            return out
        out.append((i, page))
        i += 1


def page_frames(job):
    i, addr = job
    try:
        snaps, ticks = F.frames(1, args=[1], ram=S.game(), init=S.INIT + ((0x22c08, 0), (0x1a9f4, 2)), max_insns=MAX_INSNS, fn_addr=addr, snap_sleep=True)
    except Exception as x:
        return i, None, "ERROR %s" % x
    return i, ([(bytes(F.mix(a, b)), t) for (_, _, a, b), t in zip(snaps, ticks)] if snaps else []), ""


def control(e, frames):
    """CONTROL ONLY: how many reference frames (PinMAME capture) the generated frames reproduce, all columns and columns 41-127."""
    g = glob.glob(os.path.join(MEDIA, "deff_%03d_*" % e, "reference_capture.gif"))
    if not g or not frames:
        return None, None, None
    from PIL import Image, ImageSequence
    refs = [bytes(v // 17 for v in f.convert("L").resize((128, 32)).get_flattened_data()) for f in ImageSequence.Iterator(Image.open(g[0]))]
    have = [f for f, _ in frames]
    crop = {bytes(h[y * 128 + x] for y in range(32) for x in range(41, 128)) for h in have}
    full = set(have)
    return (sum(1 for r in refs if r in full), sum(1 for r in refs if bytes(r[y * 128 + x] for y in range(32) for x in range(41, 128)) in crop), len(refs))


def main():
    out = sys.argv[1] if len(sys.argv) > 1 else os.path.join(ROOT, "rom_data", "dmd_code")
    only = [int(a) for a in sys.argv[2:]]
    effects = only or [e for e in range(1, 146)]
    from PIL import Image
    rows = []
    if 1 in effects:                                    # the attract pages, one folder each
        with Pool(4) as p:
            for i, frames, err in p.imap_unordered(page_frames, attract_pages()):
                row = write(os.path.join(out, "deff_001_pages"), i, frames, err)
                print("attract page", i, row[1:3], flush=True)
        effects = [e for e in effects if e != 1]
    with Pool(4) as p:
        results = p.imap_unordered(frames_of, effects)
        for e, frames, err in results:
            rows.append(write(out, e, frames, err))
            print(e, rows[-1][1:], flush=True)
    rows.sort()
    os.makedirs(out, exist_ok=True)
    with open(os.path.join(out, "index.csv"), "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["deff", "frames", "error", "control_exact_all_columns", "control_exact_columns_41_127", "control_reference_frames"])
        w.writerows(rows)
    print(len(rows), "effects")


def write(out, e, frames, err):
    from PIL import Image
    if True:
        d = os.path.join(out, "deff_%03d" % e)
        if frames:
            os.makedirs(os.path.join(d, "frames"), exist_ok=True)
            meta = []
            base = frames[0][1]
            for i, (f, t) in enumerate(frames):
                im = Image.new("L", (128, 32))
                im.putdata([v * 17 for v in f])
                im.save(os.path.join(d, "frames", "%03d.png" % i))
                nxt = frames[i + 1][1] if i + 1 < len(frames) else t + 1
                meta.append({"file": "frames/%03d.png" % i, "t_ms": round((t - base) * TICK_MS, 1), "duration_ms": round((nxt - t) * TICK_MS, 1), "tick": t})
            json.dump({"deff": e, "tick_ms": TICK_MS, "source": "ROM code run (Unicorn), tools/gen_code_dmd.py", "frames": meta},
                      open(os.path.join(d, "timing.json"), "w"), indent=1)
        ex_all, ex_cols, nref = control(e, frames)
        return [e, len(frames) if frames is not None else "", err, ex_all if ex_all is not None else "", ex_cols if ex_cols is not None else "", nref or ""]


if __name__ == "__main__":
    main()
